package com.smartexam.mapper;
import com.baomidou.mybatisplus.core.mapper.BaseMapper; import com.smartexam.entity.Answers; import org.apache.ibatis.annotations.Mapper; import org.apache.ibatis.annotations.Select; import java.util.List;
@Mapper public interface AnswersMapper extends BaseMapper<Answers> { @Select("SELECT * FROM answers WHERE submission_id = #{submissionId} ORDER BY id") List<Answers> selectBySubmissionId(Long submissionId); @Select("SELECT * FROM answers WHERE submission_id=#{submissionId} AND question_id=#{questionId} LIMIT 1") Answers selectOne(Long submissionId,Long questionId); @Select("SELECT DISTINCT a.submission_id FROM answers a JOIN questions q ON q.id=a.question_id WHERE q.exam_id=#{examId} AND q.question_type='SHORT_ANSWER' AND (a.grading_status IS NULL OR a.grading_status<>'REVIEWED')") List<Long> selectPendingManualSubmissionIds(Long examId); }
